def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate each interval before any processing.
    for iv in intervals:
        if (not isinstance(iv, (list, tuple))) or len(iv) != 2:
            raise ValueError("invalid interval: must be a two-element sequence")
        start, end = iv[0], iv[1]
        if not (isinstance(start, int) and isinstance(end, int)):
            raise ValueError("invalid interval: bounds must be integers")
        if start > end:
            raise ValueError("invalid interval: start must be <= end")

    values = sorted(intervals)
    out = [list(values[0])]
    for start, end in values[1:]:
        if start <= out[-1][1]:
            # Overlap (including sharing an endpoint) -> merge.
            out[-1][1] = max(out[-1][1], end)
        else:
            # Merely adjacent ranges ([1,2],[3,4]) do NOT merge.
            out.append([start, end])
    return out

