def largest_remainder(total, weights):
    if total < 0 or any(w < 0 for w in weights):
        raise ValueError("negative")
    if total == 0:
        return [0] * len(weights)
    s = sum(weights)
    if not s:
        raise ValueError("zero")
    raw = [total * w / s for w in weights]
    result = [int(x) for x in raw]  # exact floors (w,s non-negative, x>=0)
    remainders = [x - int(x) for x in raw]
    # remaining units to distribute by descending fractional remainder; ties to lower index
    slots = total - sum(result)
    order = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for i in order[:slots]:
        result[i] += 1
    return result

def dedupe_events(events):
    chosen = {}
    order = []
    for event in events:
        ident = event["id"]
        if ident not in chosen or event["seq"] >= chosen[ident]["seq"]:
            if ident not in chosen:
                chosen[ident] = event
                order.append(ident)
            elif event["seq"] > chosen[ident]["seq"]:
                chosen[ident] = event
            else:  # equal greatest seq: keep last input occurrence
                chosen[ident] = event
    result = [dict(chosen[i]) for i in order]
    result.sort(key=lambda e: e["seq"])
    return result

def dedupe_events(events):
    chosen = {}
    order = []
    for event in events:
        eid = event["id"]
        if eid not in chosen or event["seq"] >= chosen[eid]["seq"]:
            if eid in chosen:
                order.remove(eid)
            chosen[eid] = event
            order.append(eid)
    # Return new dicts sorted by seq ascending; tie-break by order of selected input occurrences.
    picked = [dict(chosen[eid]) for eid in order]
    picked.sort(key=lambda e: e["seq"])
    return picked

def dedupe_events(events):
    # Select one event per id: greatest seq; on equal seq, the last input occurrence.
    chosen = {}
    chosen_order = []
    for index, event in enumerate(events):
        eid = event["id"]
        if eid not in chosen:
            chosen[eid] = (event, index)
            chosen_order.append(eid)
        else:
            cur_event, cur_index = chosen[eid]
            if event["seq"] > cur_event["seq"] or (
                event["seq"] == cur_event["seq"] and index > cur_index
            ):
                chosen[eid] = (event, index)

    # Rebuild new dicts and sort by seq ascending, preserving input order on ties.
    result = []
    for eid in chosen_order:
        event, index = chosen[eid]
        result.append((dict(event), index))
    result.sort(key=lambda item: (item[0]["seq"], item[1]))
    return [item[0] for item in result]

