def apply_edits(text, edits):
    # Validate each edit against the original text coordinates.
    start = text
    n = len(text)
    for edit in edits:
        s, e = edit["start"], edit["end"]
        if not isinstance(s, int) or not isinstance(e, int):
            raise ValueError("non-integer edit coordinate")
        if not (0 <= s <= e <= n):
            raise ValueError("invalid edit range")
    # Sort edits by start to make overlap detection and assembly easy.
    sorted_edits = sorted(edits, key=lambda edit: (edit["start"], edit["end"]))
    for i in range(len(sorted_edits) - 1):
        a, b = sorted_edits[i], sorted_edits[i + 1]
        if a["end"] > b["start"]:
            raise ValueError("overlapping edits")
    # Apply all edits simultaneously relative to the original text.
    parts = []
    pos = 0
    for edit in sorted_edits:
        s, e = edit["start"], edit["end"]
        parts.append(text[pos:s])
        parts.append(edit["replacement"])
        pos = e
    parts.append(text[pos:])
    return "".join(parts)

