def apply_edits(text, edits):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if not isinstance(edits, list):
        raise ValueError("edits must be a list")
    n = len(text)
    # Validate each edit.
    for edit in edits:
        if not isinstance(edit, dict):
            raise ValueError("each edit must be a dict")
        start = edit.get("start")
        end = edit.get("end")
        replacement = edit.get("replacement")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("start and end must be integers")
        if not 0 <= start <= end <= n:
            raise ValueError("invalid edit bounds")
        if not isinstance(replacement, str):
            raise ValueError("replacement must be a string")
    # Check for overlaps: sort edits by start; ensure no two typed ranges overlap.
    sorted_edits = sorted(edits, key=lambda e: (e["start"], e["end"]))
    for a, b in zip(sorted_edits, sorted_edits[1:]):
        if b["start"] < a["end"]:
            raise ValueError("edits overlap")
    # Apply simultaneously relative to the original text.
    parts = []
    pos = 0
    for edit in sorted_edits:
        start, end, replacement = edit["start"], edit["end"], edit["replacement"]
        parts.append(text[pos:start])
        parts.append(replacement)
        pos = end
    parts.append(text[pos:])
    return "".join(parts)

def quorum_decision(votes, quorum):
    if quorum <= 0:
        raise ValueError("quorum")
    yes = 0
    no = 0
    for v in votes:
        if v == "yes":
            yes += 1
        elif v == "no":
            no += 1
        elif v == "abstain":
            continue
        else:
            raise ValueError("invalid vote")
    participation = yes + no
    if participation < quorum:
        return "no-quorum"
    if yes > no:
        return "yes"
    if no > yes:
        return "no"
    return "tie"

